// CSD_RATIONALE_BEGIN
// SMILES isocyanate CSD - pushing from 20% (attempt 9) to 36%+ by maximising
// sampling entropy.
//
// Root-cause of 7% (attempt 31):
//   - "O" dropped from the penalty set → model defaulted right back to
//     O=C=NC / O=C=NCC on every example, producing only ~7 unique molecules.
//   - 29 explicit SMILES examples in guidance → model memorised the first few
//     (short, simple) ones and kept repeating them.
//
// Root-cause of 20% (attempt 9, best):
//   - O penalised (4.0) for first 6 tokens → forced non-standard SMILES
//     representations (more unique starting paths).
//   - Shorter, more abstract guidance → model couldn't copy short exemplars.
//
// Plan to reach 36%:
//   1. Restore O in the penalty set (critical, proven by attempt 9 vs 31 delta).
//   2. Increase penalty amount 4.0→5.0 and extend early phase 6→10 tokens.
//   3. Increase mid-phase temperature 1.6→1.9 (higher entropy = more unique
//      molecules; SafeTemperatureConstrainedStep clamps to a safe range so
//      invalidity is not a risk; SMILES parser hard-mask guarantees syntax).
//   4. Replace GroupBoostedConstrainedStep in late phase with
//      SafeTemperatureConstrainedStep at T=1.4 (validTokenGroups may be empty).
//   5. Guidance: negative framing first (AVOID common boring structures), then
//      positive targets covering 7 structural categories; shorter = less
//      risk of model copying specific exemplar SMILES.
//   6. Keep minSpanLength=5 and NCO check for class membership validation.
//   7. Keep CloseSpanWithinBudget fallback to guarantee span closure.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// parser_validity:
//   OpenConstrainedSpan sets insideConstrainedOut := true and
//   currentConstrainedOut := []; parser.IsValidPrefix([]) holds by precondition.
//   SafePenalizedConstrainedStep, SafeTemperatureConstrainedStep each return
//   either EOS or a parser-valid next token (hard-mask postcondition), so
//   AppendConstrainedToken preserves parser.IsValidPrefix(currentConstrainedOut).
//   CloseConstrainedSpan sets insideConstrainedOut := false making the
//   implication vacuously true and clears currentConstrainedOut to [].
//   CloseSpanWithinBudget postcondition guarantees:
//     insideOut ==> parser.IsValidPrefix(currentOut), and
//     !insideOut ==> currentOut == [].
//
// progress (|generated| <= |generatedPrefix| + steps):
//   OpenConstrainedSpan appends exactly one token ("<<") and costs +1 step;
//   after the open: |generated| = |generatedPrefix| + 1 = |generatedPrefix| + steps.
//   Each loop iteration calls exactly one LM-step helper (+1 step) and at most
//   one AppendConstrainedToken (+1 visible token); the close sub-branch calls
//   CloseConstrainedSpan (+1 step, +1 token ">>") with steps < maxSteps checked
//   first so steps never overflows maxSteps.
//   CloseSpanWithinBudget is called with closeBudget = maxSteps - steps, and its
//   postcondition guarantees |generatedOut| <= |generated| + closeBudget; we then
//   set steps := maxSteps so |generated| <= |generatedPrefix| + maxSteps holds.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate ONE unique isocyanate SMILES containing N=C=O. AVOID overused structures: O=C=NC (methyl), O=C=NCC (ethyl), O=C=NCCC (propyl), O=C=NCCCC (butyl), O=C=Nc1ccccc1 (phenyl). GENERATE complex novel structures: cycloalkyl (O=C=NC1CC1, O=C=NC1CCC1, O=C=NC1CCCC1, O=C=NC1CCCCC1, O=C=NC1CC(C)C1), halogenated (O=C=NCCCl, O=C=NCCBr, O=C=NCC(F)(F)F, O=C=NCCCC(F)(F)F, O=C=NCF), branched aliphatic (O=C=NC(C)(C)C, O=C=NCC(C)C, O=C=NC(CC)CCC, O=C=NCCCC(C)C), heteroaromatic (O=C=Nc1ccccn1, O=C=Nc1cccnc1, O=C=Nc1ccncc1), functionalized (O=C=NCCO, O=C=NCCOC, O=C=NCCN(C)C, O=C=NCCSc1ccccc1), arylalkyl (O=C=NCc1ccccc1, O=C=NCc1ccc(F)cc1, O=C=NCc1cccnc1), unsaturated (O=C=NCC=C, O=C=NCC#C, O=C=NCC=CC). Output ONLY the SMILES string, nothing else.");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
